tui_main(){ if command -v dialog >/dev/null 2>&1; then dialog --clear --title 'LFSForge — Linux From Scratch Builder' --menu 'Selecciona una opción' 20 70 10 1 'Crear nuevo LFS' 2 'Reanudar build' 3 'Configuración' 4 'Validar host' 5 'Sources' 6 'Build stages' 7 'Validación' 8 'Logs' 9 'QEMU' 0 'Salir' 2>"$STATE_DIR/menu"; local x=$(cat "$STATE_DIR/menu"); clear; case "$x" in 1) tui_wizard; config_save "$CONFIG_FILE";; 2) cmd_resume;; 4) cmd_check;; 5) cmd_sources;; 6) cmd_build;; 7) cmd_validate;; 8) cmd_logs;; 9) cmd_qemu;; esac; else warn 'dialog no está instalado; usando modo CLI.'; cmd_help; fi; }
tui_wizard(){ config_defaults; read -r -p "Arquitectura [x86_64]: " x; CFG_ARCHITECTURE=${x:-x86_64}; read -r -p "Directorio LFS [/mnt/lfs]: " x; CFG_LFS_ROOT=${x:-/mnt/lfs}; read -r -p "CPU threads [$CFG_JOBS]: " x; CFG_JOBS=${x:-$CFG_JOBS}; read -r -p 'Perfil [minimal/standard/developer/custom] (standard): ' x; CFG_PROFILE=${x:-standard}; read -r -p 'Versión LFS (ej. 12.4, obligatoria para sources): ' CFG_LFS_VERSION; read -r -p '¿Construir kernel? [y/N]: ' x; [[ "$x" =~ ^[Yy]$ ]] && CFG_KERNEL_ENABLED=true; read -r -p '¿Habilitar GRUB? [y/N]: ' x; [[ "$x" =~ ^[Yy]$ ]] && CFG_BOOTLOADER_ENABLED=true; }
